// @generated by:gauntlet run:godseye-local-hermes-chat
import { randomUUID } from "node:crypto";
import { FoundationEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { fixtureAdapter } from "./foundations-helpers.js";
import { type AgentsFixture, agentsFixture } from "./helpers/agents-fixture.js";

describe("immutable existing-plan requests in Hermes output", () => {
  let f: AgentsFixture;
  let plans: FoundationEngine;
  beforeEach(async () => {
    f = await agentsFixture();
    plans = new FoundationEngine(f.store, {
      now: f.clock.now,
      adapters: [fixtureAdapter().adapter],
      approvalPolicy: () => true,
    });
  });
  afterEach(async () => {
    await f.store.close();
  });
  async function plan(foreign = false) {
    const projectId = foreign ? f.secondProject.id : f.project.id;
    const environmentId = foreign ? f.secondProject.environments[0]?.id : f.development.id;
    if (!environmentId) throw new Error("Missing proposal fixture environment");
    const configuration = await plans.registerResource(
      f.freshOwner(),
      {
        projectId,
        environmentId,
        kind: "configuration",
        name: "Exact immutable release configuration",
      },
      randomUUID(),
    );
    return plans.createPlan(
      f.freshOwner(),
      {
        projectId,
        environmentId,
        targetId: environmentId,
        expectedRevision: foreign ? f.secondProject.revision : f.project.revision,
        adapterId: "qualified-fixture",
        maxCostMicros: 1,
        tools: [],
        destinations: [],
        command: {
          kind: "deployment.release",
          intent: "deploy",
          artifactDigest: `sha256:${"a".repeat(64)}`,
          configurationRef: configuration.id,
        },
      },
      randomUUID(),
    );
  }
  async function propose(target: Awaited<ReturnType<typeof plan>>, expectedHash = target.hash) {
    const profile =
      (await f.infrastructure.agents.overview(f.freshOwner())).profiles[0] ?? (await f.create());
    const created = await f.infrastructure.agents.chatCreate(
      f.freshOwner(),
      {
        profileId: profile.id,
        expectedRevision: profile.revision,
        title: "Exact plan review",
      },
      randomUUID(),
    );
    f.provider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      stopped: true,
      output:
        "```godseye-output-v1\n" +
        JSON.stringify({
          type: "approval",
          planId: target.id,
          expectedHash,
          reason: "Please review this existing exact plan.",
        }) +
        "\n```",
    });
    await f.infrastructure.agents.chatSend(
      f.freshOwner(),
      created.conversation.id,
      {
        input: "Review a declared plan",
        expectedRevision: created.conversation.revision,
      },
      randomUUID(),
    );
    await f.work();
    return f.infrastructure.agents.chatDetail(f.freshOwner(), created.conversation.id);
  }

  it("T-AC-748 derives exact plan scope and command without approving or enqueueing", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    expect(proposal).toMatchObject({
      planId: target.id,
      expectedHash: target.hash,
      projectId: target.projectId,
      environmentId: target.environmentId,
      targetId: target.targetId,
      expectedRevision: target.expectedRevision,
      status: "pending",
    });
    expect(JSON.parse(proposal?.command ?? "null")).toEqual(target.command);
    expect(
      await f.store.db
        .select()
        .from(schema.approvals)
        .where(eq(schema.approvals.planId, target.id)),
    ).toEqual([]);
    expect(
      (await plans.listRuns(f.freshOwner())).filter((run) => run.planId === target.id),
    ).toEqual([]);
  });

  it("T-AC-748 refuses foreign plans and changed plan hashes from model output", async () => {
    const foreign = await plan(true);
    expect((await propose(foreign)).proposals).toEqual([]);
    const local = await plan();
    expect((await propose(local, "0".repeat(64))).proposals).toEqual([]);
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });

  it("T-AC-749 approves exactly once through actual Foundation authority without dispatch", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    const key = randomUUID(),
      input = { decision: "approve" as const, expectedHash: target.hash };
    const result = await f.infrastructure.agents.chatResolve(
      f.freshOwner(),
      proposal.id,
      input,
      key,
    );
    expect(result.status).toBe("approved");
    expect(
      await f.infrastructure.agents.chatResolve(f.freshOwner(), proposal.id, input, key),
    ).toEqual(result);
    expect(
      await f.store.db
        .select()
        .from(schema.approvals)
        .where(eq(schema.approvals.planId, target.id)),
    ).toHaveLength(1);
    expect(
      (await plans.listRuns(f.freshOwner())).filter((run) => run.planId === target.id),
    ).toEqual([]);
    await expect(
      f.infrastructure.agents.chatResolve(
        f.freshOwner(),
        proposal.id,
        { decision: "reject", expectedHash: target.hash },
        key,
      ),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-749 keeps rejection terminal and never creates Foundation approval", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    const rejected = await f.infrastructure.agents.chatResolve(
      f.freshOwner(),
      proposal.id,
      { decision: "reject", expectedHash: target.hash },
      randomUUID(),
    );
    expect(rejected.status).toBe("rejected");
    await expect(
      f.infrastructure.agents.chatResolve(
        f.freshOwner(),
        proposal.id,
        { decision: "approve", expectedHash: target.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });

  it("T-AC-749 denies agent self-approval, stale owner verification and changed hashes", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    const actor = f.freshOwner(),
      service = { ...actor, kind: "service" as const, projectIds: [f.project.id] };
    const input = { decision: "approve" as const, expectedHash: target.hash };
    await expect(
      f.infrastructure.agents.chatResolve(service, proposal.id, input, randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
    await expect(
      f.infrastructure.agents.chatResolve(
        actor,
        proposal.id,
        { ...input, expectedHash: "0".repeat(64) },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    f.clock.advance(300001);
    await expect(
      f.infrastructure.agents.chatResolve(actor, proposal.id, input, randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });

  it("T-AC-749 refuses expired proposals without renewing authority", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    f.clock.advance(3600001);
    await expect(
      f.infrastructure.agents.chatResolve(
        f.freshOwner(),
        proposal.id,
        { decision: "approve", expectedHash: target.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });

  it("T-AC-749 permits protective rejection after expiry with old owner verification", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    const oldOwner = f.freshOwner();
    f.clock.advance(3600001);
    const result = await f.infrastructure.agents.chatResolve(
      oldOwner,
      proposal.id,
      { decision: "reject", expectedHash: target.hash },
      randomUUID(),
    );
    expect(result.status).toBe("rejected");
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });

  it("T-AC-749 refuses approval after the proposal's source environment is held", async () => {
    const target = await plan(),
      detail = await propose(target),
      proposal = detail.proposals[0];
    if (!proposal) throw new Error("Expected a pending plan proposal");
    await f.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, f.development.id));
    await expect(
      f.infrastructure.agents.chatResolve(
        f.freshOwner(),
        proposal.id,
        { decision: "approve", expectedHash: target.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect(await f.store.db.select().from(schema.approvals)).toEqual([]);
  });
});
